CREATE OR REPLACE FUNCTION public.restore_post(p_post_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.posts WHERE id=p_post_id AND user_id=auth.uid() AND is_deleted IS TRUE) THEN
  RAISE EXCEPTION 'Post not found or not owned' USING ERRCODE='42501';
 END IF;
 UPDATE public.posts SET is_deleted=false WHERE id=p_post_id AND user_id=auth.uid();
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.toggle_repost(p_post_id uuid, p_user_id uuid, p_comment text DEFAULT ''::text)
 RETURNS TABLE(reposted boolean, count integer, out_comment text, out_time timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_exists boolean; v_count integer; v_time timestamptz;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM p_user_id THEN
  RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
 END IF;
 SELECT EXISTS(SELECT 1 FROM public.reposts r WHERE r.post_id=p_post_id AND r.user_id=p_user_id) INTO v_exists;
 IF v_exists THEN
  DELETE FROM public.reposts r WHERE r.post_id=p_post_id AND r.user_id=p_user_id;
  UPDATE public.posts p SET repost_count=greatest(0,coalesce(p.repost_count,0)-1) WHERE p.id=p_post_id RETURNING p.repost_count INTO v_count;
  RETURN QUERY SELECT false,v_count,''::text,null::timestamptz;
 ELSE
  v_time:=now();
  INSERT INTO public.reposts(post_id,user_id,comment,created_at) VALUES(p_post_id,p_user_id,coalesce(p_comment,''),v_time);
  UPDATE public.posts p SET repost_count=coalesce(p.repost_count,0)+1 WHERE p.id=p_post_id RETURNING p.repost_count INTO v_count;
  RETURN QUERY SELECT true,v_count,coalesce(p_comment,''),v_time;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.toggle_repost(p_post_id uuid, p_comment text DEFAULT ''::text)
 RETURNS TABLE(reposted boolean, new_count integer, repost_comment text, reposted_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_exists boolean;
  v_count integer;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if not exists (select 1 from posts where id = p_post_id) then
    raise exception 'Post not found';
  end if;

  select exists(
    select 1 from reposts where post_id = p_post_id and user_id = v_user_id
  ) into v_exists;

  if v_exists then
    delete from reposts where post_id = p_post_id and user_id = v_user_id;
    update posts set repost_count = greatest(0, repost_count - 1) where id = p_post_id returning repost_count into v_count;
    return query select false, v_count, ''::text, null::timestamptz;
  else
    insert into reposts (post_id, user_id, comment) values (p_post_id, v_user_id, coalesce(p_comment, ''));
    update posts set repost_count = repost_count + 1 where id = p_post_id returning repost_count into v_count;
    return query select true, v_count, coalesce(p_comment, ''), now();
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION privacy_v2_private.protected_post_retirement_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE protected boolean; d privacy_v2_private.post_deletions%rowtype;
BEGIN
 SELECT EXISTS(SELECT 1 FROM privacy_v2_private.protected_post_origins WHERE post_id=OLD.id AND owner_id=OLD.user_id) INTO protected;
 IF TG_OP='DELETE' THEN
  IF NOT protected THEN RETURN OLD; END IF;
  INSERT INTO privacy_v2_private.post_deletions(post_id,owner_id,purge_after,permanent,previous_state,previous_hidden)
   VALUES(OLD.id,OLD.user_id,now(),true,OLD.publishing_state,OLD.is_hidden)
   ON CONFLICT(post_id) DO UPDATE SET permanent=true,purge_after=now();
  UPDATE public.posts SET is_deleted=true,is_hidden=true,publishing_state='failed' WHERE id=OLD.id;
  RETURN NULL;
 END IF;
 SELECT * INTO d FROM privacy_v2_private.post_deletions WHERE post_id=OLD.id FOR UPDATE;
 IF OLD.is_deleted IS TRUE AND NEW.is_deleted IS DISTINCT FROM TRUE THEN
  IF d.post_id IS NULL OR d.permanent OR d.purge_after<=now()
    OR EXISTS(SELECT 1 FROM privacy_v2_private.verification_posts WHERE post_id=OLD.id)
    OR (protected AND EXISTS(SELECT 1 FROM public.post_media_assets WHERE post_id=OLD.id AND status<>'ready')) THEN
   RAISE EXCEPTION 'Post cannot be restored' USING ERRCODE='23514';
  END IF;
  NEW.publishing_state:=d.previous_state; NEW.is_hidden:=d.previous_hidden; NEW.deleted_at:=NULL;
  DELETE FROM privacy_v2_private.post_deletions WHERE post_id=OLD.id;
  RETURN NEW;
 END IF;
 IF NEW.is_deleted IS TRUE OR (protected AND NEW.publishing_state='failed' AND NEW.is_hidden IS TRUE) THEN
  INSERT INTO privacy_v2_private.post_deletions(post_id,owner_id,purge_after,permanent,previous_state,previous_hidden)
   VALUES(OLD.id,OLD.user_id,now()+interval '7 days',NEW.publishing_state='failed',OLD.publishing_state,coalesce(OLD.is_hidden,false))
   ON CONFLICT(post_id) DO UPDATE SET permanent=post_deletions.permanent OR excluded.permanent;
  SELECT * INTO d FROM privacy_v2_private.post_deletions WHERE post_id=OLD.id;
  NEW.is_deleted:=true; NEW.is_hidden:=true; NEW.deleted_at:=d.deleted_at;
  IF protected AND d.permanent THEN
   NEW.publishing_state:='failed';
   PERFORM privacy_v2_private.queue_protected_retirement(OLD.id,OLD.user_id);
  END IF;
 END IF;
 RETURN NEW;
END $function$
